import { useState, useEffect } from 'react';
import { Task, DayData, TomorrowPlan } from '../types';

export const useTrackerData = () => {
  // Initialize default tasks for any day
  const getDefaultTasks = (day: number): Task[] => {
    const isWeekday = new Date(2026, 3, day).getDay() >= 1 && new Date(2026, 3, day).getDay() <= 5;

    return [
      // Morning Routine
      { id: '1', category: 'Morning Routine', title: 'Wake up and freshen up', time: '6:00–6:30 AM', completed: false, skipped: false },
      { id: '2', category: 'Morning Routine', title: '10 min meditation + 10 min manifestation & gratitude', time: '6:30–6:50 AM', completed: false, skipped: false },
      { id: '3', category: 'English Learning', title: '5 new words with sentences', time: '7:00–8:15 AM', completed: false, skipped: false },
      { id: '4', category: 'English Learning', title: '10 min book reading in English', time: '7:00–8:15 AM', completed: false, skipped: false },
      { id: '5', category: 'English Learning', title: '1 YouTube lecture (finish completely)', time: '7:00–8:15 AM', completed: false, skipped: false },

      // Trading
      { id: '6', category: 'Trading', title: 'Trade planning + minimum 2–3 live trades', time: '9:00–9:40 AM', completed: false, skipped: false },
      { id: '7', category: 'Trading', title: isWeekday ? 'Trade analysis and learning (after office)' : '2 full hours of trading practice', time: isWeekday ? '7:00–7:30 PM' : 'Full session', completed: false, skipped: false },

      // Coding/DSA
      { id: '8', category: 'Coding/DSA', title: isWeekday ? 'DSA + Flutter questions (30 min)' : 'DSA practice (1 hour)', time: isWeekday ? '9:00–9:30 PM' : 'Flexible', completed: false, skipped: false },

      // Flutter/React Development
      { id: '9', category: 'Flutter/React', title: getDevelopmentTask(day), time: getDevelopmentTime(day, isWeekday), completed: false, skipped: false },

      // Night Review
      { id: '10', category: 'Night Review', title: 'Check all completed/missed tasks', time: 'Before sleep', completed: false, skipped: false },
      { id: '11', category: 'Night Review', title: 'Plan next day\'s topics', time: 'Before sleep', completed: false, skipped: false },
      { id: '12', category: 'Night Review', title: 'Write short note before sleeping', time: 'Before sleep', completed: false, skipped: false },
    ];
  };

  const getDevelopmentTask = (day: number) => {
    if (day <= 30) return 'Flutter development session';
    return 'Flutter + React development session';
  };

  const getDevelopmentTime = (day: number, isWeekday: boolean) => {
    if (day <= 30) {
      return isWeekday ? '9:30 PM–1:00 AM (3 hrs)' : '10 hrs Flutter';
    }
    return isWeekday ? '1.5 hrs Flutter + 2 hrs React' : '5 hrs Flutter + 5 hrs React';
  };

  const calculatePoints = (tasks: Task[]): number => {
    let totalPoints = 0;

    tasks.forEach(task => {
      if (task.completed) {
        // Reward points
        if (task.category === 'Trading') totalPoints += 10;
        else if (task.category === 'Flutter/React') totalPoints += 10;
        else if (task.category === 'Coding/DSA') totalPoints += 8;
        else if (task.category === 'Morning Routine') totalPoints += 5;
        else if (task.category === 'Night Review') totalPoints += 5;
        else totalPoints += 3; // English Learning
      } else if (task.skipped) {
        // Penalty points
        if (task.category === 'Trading') totalPoints -= 10;
        else if (task.category === 'Flutter/React') totalPoints -= 10;
        else if (task.category === 'Coding/DSA') totalPoints -= 8;
        else if (task.category === 'Morning Routine') totalPoints -= 5;
        else if (task.category === 'Night Review') totalPoints -= 5;
        else totalPoints -= 3; // English Learning
      }
    });

    // Bonus for completing all tasks
    const allCompleted = tasks.every(task => task.completed);
    if (allCompleted) {
      totalPoints += 20;
    }

    // Penalty for missing all tasks
    const allMissed = tasks.every(task => !task.completed);
    if (allMissed) {
      totalPoints -= 30;
    }

    return totalPoints;
  };

  const calculateGrade = (tasks: Task[]): string => {
    const completedTasks = tasks.filter(t => t.completed).length;
    const totalTasks = tasks.length;
    const percentage = (completedTasks / totalTasks) * 100;

    if (percentage >= 90) return 'A';
    if (percentage >= 80) return 'B';
    if (percentage >= 70) return 'C';
    if (percentage >= 60) return 'D';
    return 'F';
  };

  const calculateCompletionPercentage = (tasks: Task[]): number => {
    const completedTasks = tasks.filter(t => t.completed).length;
    const totalTasks = tasks.length;
    return totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;
  };

  // State management
  const [currentDay, setCurrentDay] = useState(1);
  const [calendarData, setCalendarData] = useState<DayData[]>([]);
  const [points, setPoints] = useState(0);
  const [streak, setStreak] = useState(0);
  const [badges, setBadges] = useState<string[]>([]);
  const [tomorrowPlan, setTomorrowPlan] = useState<TomorrowPlan>({
    englishTopic: '',
    tradingStrategy: '',
    dsaTopic: '',
    flutterReactChapter: ''
  });
  const [darkMode, setDarkMode] = useState(true);

  // Initialize data from localStorage
  useEffect(() => {
    const savedData = localStorage.getItem('trackerData');
    if (savedData) {
      const parsed = JSON.parse(savedData);
      setCurrentDay(parsed.currentDay || 1);
      setCalendarData(parsed.calendarData || []);
      setPoints(parsed.points || 0);
      setStreak(parsed.streak || 0);
      setBadges(parsed.badges || []);
      setTomorrowPlan(parsed.tomorrowPlan || {
        englishTopic: '',
        tradingStrategy: '',
        dsaTopic: '',
        flutterReactChapter: ''
      });
      setDarkMode(parsed.darkMode !== undefined ? parsed.darkMode : true);
    } else {
      // Initialize with 180 days of default tasks
      const initialData: DayData[] = Array.from({ length: 180 }, (_, i) => ({
        day: i + 1,
        date: new Date(2026, 3, i + 1).toISOString(),
        tasks: getDefaultTasks(i + 1),
        points: 0,
        streak: 0,
        completed: false,
        grade: 'F'
      }));
      setCalendarData(initialData);
    }
  }, []);

  // Save to localStorage whenever any state changes
  useEffect(() => {
    const data = {
      currentDay,
      calendarData,
      points,
      streak,
      badges,
      tomorrowPlan,
      darkMode
    };
    localStorage.setItem('trackerData', JSON.stringify(data));
  }, [currentDay, calendarData, points, streak, badges, tomorrowPlan, darkMode]);

  // Get current day's tasks
  const getCurrentDayTasks = (): Task[] => {
    if (calendarData.length === 0) return getDefaultTasks(currentDay);
    const currentDayData = calendarData.find(d => d.day === currentDay);
    return currentDayData ? currentDayData.tasks : getDefaultTasks(currentDay);
  };

  // Update task for any day
  const updateTask = (day: number, taskId: string, updates: Partial<Task>) => {
    setCalendarData(prev => prev.map((dayData, index) => {
      if (dayData.day === day) {
        const updatedTasks = dayData.tasks.map(task => {
          if (task.id === taskId) {
            return { ...task, ...updates };
          }
          return task;
        });

        const completionPercentage = calculateCompletionPercentage(updatedTasks);
        const grade = calculateGrade(updatedTasks);
        const dayPoints = calculatePoints(updatedTasks);

        return { 
          ...dayData, 
          tasks: updatedTasks, 
          grade,
          points: dayPoints,
          completed: completionPercentage === 100
        };
      }
      return dayData;
    }));
  };

  // Toggle task completion
  const toggleTask = (day: number, taskId: string) => {
    const dayData = calendarData.find(d => d.day === day);
    if (dayData) {
      const task = dayData.tasks.find(t => t.id === taskId);
      if (task) {
        updateTask(day, taskId, { 
          completed: !task.completed, 
          skipped: false 
        });
      }
    }
  };

  // Skip task
  const skipTask = (day: number, taskId: string) => {
    const dayData = calendarData.find(d => d.day === day);
    if (dayData) {
      const task = dayData.tasks.find(t => t.id === taskId);
      if (task) {
        updateTask(day, taskId, { 
          skipped: !task.skipped, 
          completed: false 
        });
      }
    }
  };

  // Complete night review and move to next day
  const completeNightReview = () => {
    const todayData = calendarData.find(d => d.day === currentDay);
    if (todayData) {
      const dayPoints = calculatePoints(todayData.tasks);
      const newStreak = todayData.completed ? streak + 1 : 0;

      // Check for badges
      const newBadges = [...badges];
      if (newStreak === 7 && !badges.includes('Week Warrior')) {
        newBadges.push('Week Warrior');
      }
      if (newStreak === 30 && !badges.includes('Month Master')) {
        newBadges.push('Month Master');
      }
      if (currentDay === 180 && !badges.includes('Champion')) {
        newBadges.push('Champion');
      }

      // Update today's data with completion
      const updatedTodayData = {
        ...todayData,
        completed: true,
        points: dayPoints
      };

      setCalendarData(prev => prev.map(d => d.day === currentDay ? updatedTodayData : d));

      setPoints(points + dayPoints);
      setStreak(newStreak);
      setBadges(newBadges);

      // Move to next day
      setCurrentDay(currentDay + 1);
    }
  };

  // Get current day's data
  const getCurrentDayData = (): DayData | undefined => {
    return calendarData.find(d => d.day === currentDay);
  };

  return {
    // State
    currentDay,
    calendarData,
    points,
    streak,
    badges,
    tomorrowPlan,
    darkMode,

    // Current day data
    currentDayTasks: getCurrentDayTasks(),
    currentDayData: getCurrentDayData(),

    // Actions
    setCurrentDay,
    setDarkMode,
    toggleTask,
    skipTask,
    completeNightReview,
    updateTask,
    setTomorrowPlan,

    // Utilities
    calculatePoints,
    calculateGrade,
    calculateCompletionPercentage
  };
};
